export function range(start, end) {
  const out = []
  for (let i = start; i <= end; i += 1) out.push(i)
  return out
}

import test from "node:test"
import assert from "node:assert/strict"
import { range } from "../src/range.mjs"

test("range 包含 end", () => {
  assert.deepEqual(range(1, 3), [1, 2, 3])
})
